code_sketch:
import threading

_state = threading.local()                  # attributes are per thread

def current() -> RequestContext:
    try:
        return _state.ctx                   # this thread's own value
    except AttributeError:
        _state.ctx = RequestContext()       # lazily created per thread
        return _state.ctx

